def optimal_response(model, x, y, q):
    """Build the optimal response payload plus the certificate diagnostics."""
    loads = _loads_of(model, x)
    if model.M:
        mlu = float(np.max(loads / np.asarray(model.caps, dtype=float)))
    else:
        mlu = 0.0
    migration = 0.0
    for j in range(model.P):
        migration += abs(x[j] - model.a[j])
    migration *= 0.5

    y = np.asarray(y, dtype=float)
    q = np.asarray(q, dtype=float)
    max_viol, L = _dual_report(model, y, q)

    flows = []
    pos = 0
    for count in model.counts:
        flows.append([_clean(x[pos + i]) for i in range(count)])
        pos += count

    response = {
        "epoch": model.epoch,
        "status": "optimal",
        "flows": flows,
        "loads": _clean_list(loads),
        "mlu": _clean(mlu),
        "migration": _clean(migration),
        "dual": {
            "inequality": _clean_list(y),
            "equality": _clean_list(q),
        },
    }
    return response, max_viol, L


def optimal_with_certificate(model, x, y, q):
    """Optimal response, repairing the dual certificate when needed."""
    response, max_viol, L = optimal_response(model, x, y, q)
    if max_viol <= 1e-8 and abs(L - response["mlu"]) <= 1e-6:
        if primal_violation(model, x, response["mlu"]) <= 1e-9:
            return response
    for relax in (0.0, 1e-9, 1e-7):
        y2, q2 = solve_dual_lp(model, relax=relax)
        if y2 is None:
            continue
        response2, viol2, L2 = optimal_response(model, x, y2, q2)
        if viol2 <= 1e-8 and abs(L2 - response2["mlu"]) <= 1e-6:
            if primal_violation(model, x, response2["mlu"]) <= 1e-9:
                return response2
    # last resort: an equivalent LP without the t variables
    status2, x2 = solve_reduced(model)
    if status2 == 0 and x2 is not None:
        y2, q2 = solve_dual_lp(model)
        if y2 is not None:
            response2, viol2, L2 = optimal_response(model, x2, y2, q2)
            if viol2 <= 1e-8 and abs(L2 - response2["mlu"]) <= 1e-6:
                if primal_violation(model, x2, response2["mlu"]) <= 1e-9:
                    return response2
    return response


def build_response(raw):
    """Turn one input line into one response object."""
    pr = parse_request(raw)
    if pr is None:
        return {"status": "invalid"}
    model = Model(pr)
    status, x, y, q = solve_primal(model)
    if status == 0 and x is not None:
        return optimal_with_certificate(model, x, y, q)
    # the canonical LP is infeasible (or the solver failed): a Farkas witness
    # proves infeasibility on its own
    cert = farkas_certificate(model)
    if cert is not None:
        y, q = cert
        return {"epoch": model.epoch, "status": "infeasible",
                "certificate": {"inequality": _clean_list(y),
                                "equality": _clean_list(q)}}
    # no witness found: cross check feasibility with the equivalent reduced LP
    status2, x2 = solve_reduced(model)
    if status2 == 0 and x2 is not None:
        y2, q2 = solve_dual_lp(model)
        if y2 is not None:
            return optimal_with_certificate(model, x2, y2, q2)
        return optimal_response(model, x2, np.zeros(model.R),
                                np.zeros(model.K))[0]
    return {"epoch": model.epoch, "status": "infeasible",
            "certificate": {"inequality": [0.0] * model.R,
                            "equality": [0.0] * model.K}}


